mapper.select:
SELECT 
FROM ecom_ad_campaign c


    c.store_id = #{storeId}
    AND c.status = #{status}
    AND c.ad_type = #{adType}

        AND (c.name LIKE CONCAT('%', #{keyword}, '%') OR c.platform_campaign_id = #{keyword} OR c.tags LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY c.store_id, c.name

SELECT 
FROM ecom_ad_campaign c

WHERE c.id = #{id}

SELECT 'CAMPAIGN' AS level, c.id, c.store_id, s.name AS store_name, s.currency, c.id AS campaign_id, c.name AS campaign_name, c.tags AS campaign_tags, c.ad_type, c.name, c.status, c.platform_campaign_id AS platform_id, c.daily_budget AS budget FROM ecom_ad_campaign c JOIN ecom_store s ON s.id = c.store_id WHERE 1 = 1 AND c.status <> 'ARCHIVED'
AND c.store_id IN #{i}
AND c.id = #{campaignId} AND c.ad_type = #{adType} AND c.name LIKE CONCAT('%', #{keyword}, '%') ORDER BY c.store_id, c.name
